import sys, random, warnings, io
sys.path.insert(0,'/workspace/task/source')
warnings.simplefilter('ignore')
from Bio.Seq import Seq
from Bio.SeqFeature import (SimpleLocation, CompoundLocation, SeqFeature, Location,
                            BeforePosition, AfterPosition, ExactPosition)
from Bio.SeqIO.InsdcIO import _insdc_location_string
from Bio.SeqRecord import SeqRecord

def manual_extract(loc, seq):
    out = ""
    for p in loc.parts:
        s = str(seq[int(p.start):int(p.end)])
        if p.strand == -1:
            s = str(Seq(s).reverse_complement())
        out += s
    return out

random.seed(1234)
fails = {"A_roundtrip":0, "B_involution":0, "C_extract":0, "D_stranded_content":0, "E_strandless_content":0, "F_mixed":0}
examples = {}
for trial in range(4000):
    L = random.randint(20, 80)
    seq = Seq("".join(random.choice("ACGT") for _ in range(L)))
    rc = seq.reverse_complement()
    n = random.choice([1,1,2,2,3,4])
    # random disjoint intervals
    pts = sorted(random.sample(range(L+1), 2*n))
    ivs = [(pts[2*i], pts[2*i+1]) for i in range(n) if pts[2*i] < pts[2*i+1]]
    if not ivs: continue
    mode = random.choice(["all+","all-","allNone","all0","mixed"])
    parts=[]
    for (a,b) in ivs:
        if mode=="all+": st=1
        elif mode=="all-": st=-1
        elif mode=="allNone": st=None
        elif mode=="all0": st=0
        else: st=random.choice([1,-1,None,0])
        parts.append(SimpleLocation(a,b,st))
    if random.random()<0.3 and len(parts)>1:
        random.shuffle(parts)   # arbitrary part order (e.g. origin spanning)
    loc = parts[0] if len(parts)==1 else CompoundLocation(parts, operator=random.choice(["join","join","order"]))
    # C: extract vs manual
    if str(loc.extract(seq)) != manual_extract(loc, seq):
        fails["C_extract"]+=1; examples.setdefault("C_extract",str(loc))
    # B: involution
    f = loc._flip(L)
    if f._flip(L) != loc:
        fails["B_involution"]+=1; examples.setdefault("B_involution",(str(loc),str(f),str(f._flip(L))))
    # A: write/parse round trip (join only; 'order' also fine)
    s = _insdc_location_string(loc, L)
    try:
        back = Location.fromstring(s, L)
    except Exception as e:
        fails["A_roundtrip"]+=1; examples.setdefault("A_roundtrip",(str(loc), s, repr(e))); back=None
    if back is not None:
        # normalise strand None/0 -> 1 for comparison of content
        if manual_extract(back, seq) != manual_extract(loc, seq).replace("","") and not any(p.strand in (None,0) for p in loc.parts):
            fails["A_roundtrip"]+=1; examples.setdefault("A_roundtrip",(str(loc), s, str(back)))
        elif any(p.strand in (None,0) for p in loc.parts):
            # strand None written as plus: content should be same as treating None as +1
            norm = CompoundLocation([SimpleLocation(p.start,p.end,1 if p.strand in (None,0) else p.strand) for p in loc.parts], loc.operator) if len(loc.parts)>1 else SimpleLocation(loc.start,loc.end, 1 if loc.strand in (None,0) else loc.strand)
            if manual_extract(back, seq) != manual_extract(norm, seq):
                fails["A_roundtrip"]+=1; examples.setdefault("A_roundtrip",(str(loc), s, str(back)))
    # D/E/F content after flip
    orig = manual_extract(loc, seq)
    flipped = manual_extract(f, rc)
    strands = {p.strand for p in loc.parts}
    if strands <= {1,-1}:
        if flipped != orig:
            fails["D_stranded_content"]+=1; examples.setdefault("D_stranded_content",(str(loc),str(f),orig,flipped))
    elif strands <= {None,0}:
        if flipped != str(Seq(orig).reverse_complement()):
            fails["E_strandless_content"]+=1; examples.setdefault("E_strandless_content",(str(loc),str(f),orig,flipped))
    else:
        if flipped != orig and flipped != str(Seq(orig).reverse_complement()):
            fails["F_mixed"]+=1; examples.setdefault("F_mixed",(str(loc),str(f),orig,flipped))
print(fails)
for k,v in examples.items():
    print(k, v)
